dti = DatetimeIndex(["1970-06-15"])

offsets = [
    QuarterEnd(2**62),
    YearEnd(2**62),
    YearBegin(-(2**63)),
    BYearEnd(2**63 - 1),
    HalfYearEnd(-(2**63))
]

for offset in offsets:
    try:
        result_dti = dti + offset
        probe("dti = DatetimeIndex([\"1970-06-15\"]); dti + offset and dti[0] + offset for offset in [QuarterEnd(2**62), YearEnd(2**62), YearBegin(-(2**63)), BYearEnd(2**63 - 1), HalfYearEnd(-(2**63))]", result_dti)
